// Message codes by name.
export const MSP_CODES = Object.freeze(Object.fromEntries(
    Object.values(MESSAGES).map((message) => [message.name, message.code])));

export const BY_CODE = new Map(Object.values(MESSAGES).map((message) => [message.code, message]));
